def process(
    input_stream: TextIO,
    output_stream: TextIO,
    extension: str = "py",
    config: Config = DEFAULT_CONFIG,
) -> bool:
    """Parses a stream of code with unsorted import sections and sorts them.

    The function reads from the provided `input_stream`, identifies and sorts the import statements within it, 
    and writes the sorted content to the specified `output_stream`. It supports Python files by default but can handle other extensions as well.

    Parameters:
        input_stream (TextIO): A text stream containing code with unsorted import sections.
        output_stream (TextIO): The text stream where the sorted import statements will be written.
        extension (str, optional): The file extension or rules for handling imports. Defaults to "py".
            Choices: ["py", "pyi", "pyx"].
        config (Config, optional): Configuration settings for sorting imports. Defaults to `isort.settings.DEFAULT_CONFIG`.

    Returns:
        bool: True if there were changes made to the import statements that required sorting; otherwise, False.

    Examples:
        To process a Python file and output the sorted content:
        ```python
        with open("input_file.py", "r") as input_stream, open("output_file.py", "w") as output_stream:
            made_changes = process(input_stream, output_stream)
        ```

        To specify a different file extension for handling imports:
        ```python
        with open("input_file.pyx", "r") as input_stream, open("output_file.pyx", "w") as output_stream:
            made_changes = process(input_stream, output_stream, extension="pyx")
        ```
    """
    line_separator: str = config.line_ending
    add_imports: List[str] = [format_natural(addition) for addition in config.add_imports]
    import_section: str = ""
    next_import_section: str = ""
    next_cimports: bool = False
    in_quote: str = ""
    first_comment_index_start: int = -1
    first_comment_index_end: int = -1
    contains_imports: bool = False
    in_top_comment: bool = False
    first_import_section: bool = True
    indent: str = ""
    isort_off: bool = False
    code_sorting: Union[bool, str] = False
    code_sorting_section: str = ""
    code_sorting_indent: str = ""
    cimports: bool = False
    made_changes: bool = False
    stripped_line: str = ""
    end_of_file: bool = False
    verbose_output: List[str] = []

    if config.float_to_top:
        new_input = ""
        current = ""
        isort_off = False
        for line in chain(input_stream, (None,)):
            if isort_off and line is not None:
                if line == "# isort: on\n":
                    isort_off = False
                new_input += line
            elif line in ("# isort: split\n", "# isort: off\n", None) or str(line).endswith(
                "# isort: split\n"
            ):
                if line == "# isort: off\n":
                    isort_off = True
                if current:
                    if add_imports:
                        add_line_separator = line_separator or "\n"
                        current += add_line_separator + add_line_separator.join(add_imports)
                        add_imports = []
                    parsed = parse.file_contents(current, config=config)
                    verbose_output += parsed.verbose_output
                    extra_space = ""
                    while current and current[-1] == "\n":
                        extra_space += "\n"
                        current = current[:-1]
                    extra_space = extra_space.replace("\n", "", 1)
                    sorted_output = output.sorted_imports(
                        parsed, config, extension, import_type="import"
                    )
                    made_changes = made_changes or _has_changed(
                        before=current,
                        after=sorted_output,
                        line_separator=parsed.line_separator,
                        ignore_whitespace=config.ignore_whitespace,
                    )
                    new_input += sorted_output
                    new_input += extra_space
                    current = ""
                new_input += line or ""
            else:
                current += line or ""

        input_stream = StringIO(new_input)

    for index, line in enumerate(chain(input_stream, (None,))):
        if line is None:
            if index == 0 and not config.force_adds:
                return False

            not_imports = True
            end_of_file = True
            line = ""
            if not line_separator:
                line_separator = "\n"

            if code_sorting and code_sorting_section:
